class State(TypedDict):
    count: int
    budget: str
    gpu: ChoiseGPU
    cpu: ChoiseCPU
    ram: ChoiseRAM
    ssd: ChoiseSSD
    result: ServerAnalysisResponse


def chiose_gpu(state: State) -> dict:
    request = gpu_template.invoke({"money": state["budget"], "data": data["Видеокарты"]})
    chain = gpu_template | yandex_gpt | parcer_gpu
    result = chain.invoke({"money": state["budget"], "data": data["Видеокарты"]})
    count_request = yandex_gpt.get_num_tokens(request.to_string())
    count_answer = yandex_gpt.get_num_tokens(str(result))
    count = count_request + count_answer
